<template><MerchantShell title="门店订单发货" :manager="manager"><template v-if="order && defaults"><view class="merchant-card"><text class="merchant-subtitle">{{ order.order_id }}</text><text>{{ order.real_name }} · {{ order.user_phone }}</text><view class="merchant-note">{{ order.user_address }}</view></view><view class="merchant-card"><text class="merchant-subtitle">发货方式</text><view class="merchant-tabs"><button v-for="option in deliveryModes" :key="option.type" :class="{active:type===option.type}" :disabled="manager.busy.value || option.disabled" @tap="type=option.type">{{ option.label }}</button></view><template v-if="type===1"><view class="merchant-form-field"><text>快递公司</text><picker :range="carriers" range-key="name" :value="carrierIndex<0 ? 0 : carrierIndex" @change="chooseCarrier"><view>{{ carriers[carrierIndex]?.name || '请选择真实可用快递公司' }} ⌄</view></picker></view><view class="merchant-form-field"><text>快递单号</text><input v-model="tracking" maxlength="64" placeholder="填写本次发货的真实快递单号" /></view></template><template v-else-if="type===2"><view class="merchant-form-field"><text>配送员</text><picker :range="agents" range-key="nickname" :value="agentIndex<0 ? 0 : agentIndex" @change="chooseAgent"><view>{{ agents[agentIndex]?.nickname || '请选择当前门店可用配送员' }} ⌄</view></picker><text v-if="agents[agentIndex]" class="merchant-note">{{ agents[agentIndex]?.phone }}</text></view></template><view v-else class="merchant-form-field"><text>虚拟发货内容</text><textarea v-model="content" :maxlength="500" placeholder="填写实际交付给客户的内容" /></view><view class="merchant-warning">{{ order.actions.electronic_waybill.reason || '电子面单当前暂不可用，请使用真实手工物流信息。' }}</view></view><view class="merchant-card"><text class="merchant-subtitle">本次发货商品</text><view class="merchant-tabs"><button :class="{active:!split}" @tap="split=false">整单发货</button><button :class="{active:split}" :disabled="!order.actions.split_delivery.available" @tap="split=true">选择商品拆单发货</button></view><view v-for="cart in carts" :key="cart.id"><MerchantCart :cart="cart" /><view v-if="split && cart.split_surplus_num>0" class="merchant-choice"><view class="merchant-check" :class="{on:!!quantities[cart.cart_id]}" @tap="toggle(cart)">{{ quantities[cart.cart_id] ? '✓' : '' }}</view><text class="merchant-choice-label">最多 {{ cart.split_surplus_num }} 件</text><button :disabled="!quantities[cart.cart_id] || (quantities[cart.cart_id] || 0)<=1" @tap="quantity(cart,-1)">−</button><text>{{ quantities[cart.cart_id] || 0 }}</text><button :disabled="(quantities[cart.cart_id] || 0)>=cart.split_surplus_num" @tap="quantity(cart,1)">＋</button></view></view><text v-if="split && !order.actions.split_delivery.available" class="merchant-note">{{ order.actions.split_delivery.reason }}</text><text v-if="error" class="merchant-money">{{ error }}</text><button class="merchant-full-button" :disabled="manager.busy.value || !(split ? order.actions.split_delivery.available && manager.context.value?.data.capabilities.split_delivery : order.actions.manual_delivery.available && manager.context.value?.data.capabilities.manual_delivery)" @tap="submit">核对并发货</button></view></template></MerchantShell></template>
<script setup lang="ts">
import { computed,ref } from 'vue';import MerchantShell from '@/components/merchantOrders/MerchantShell.vue';import MerchantCart from '@/components/merchantOrders/MerchantCart.vue';import { useMerchantOrders } from '@/composables/useMerchantOrders';import { isMerchantDetail,isMerchantDelivery,isMerchantDeliveryGain,isMerchantCart,isMerchantAgents,isMerchantCarriers,merchantOrderId } from '@/utils/merchantOrders';import type { MerchantOrderDetail,MerchantDeliveryDefaults,MerchantOrderCart,MerchantDeliveryAgent,MerchantCarrier } from '@/types/merchantOrders';
const order=ref<MerchantOrderDetail|null>(null),defaults=ref<MerchantDeliveryDefaults|null>(null),carts=ref<MerchantOrderCart[]>([]),agents=ref<MerchantDeliveryAgent[]>([]),carriers=ref<MerchantCarrier[]>([]),type=ref(1),carrierIndex=ref(-1),agentIndex=ref(-1),tracking=ref(''),content=ref(''),split=ref(false),quantities=ref<Record<string,number>>({}),error=ref('');let orderId='';
const manager=useMerchantOrders({query(query){orderId=query.orderId||query.id||'';},clear(){order.value=null;defaults.value=null;carts.value=[];agents.value=[];carriers.value=[];carrierIndex.value=-1;agentIndex.value=-1;tracking.value='';content.value='';split.value=false;quantities.value={};error.value='';},async load(controller){const valid=controller.fence();if(!merchantOrderId(orderId))throw Error('订单编号无效');const detail=await controller.read(`detail/${encodeURIComponent(orderId)}`,isMerchantDetail);if(!valid())return;if(detail.data.order_id!==orderId)throw Error('订单响应不匹配');const [gain,shipping,cartRows,staff,express]=await Promise.all([controller.read(`delivery/gain/${encodeURIComponent(orderId)}`,isMerchantDeliveryGain),controller.read('delivery/config',isMerchantDelivery),controller.read(`split_cart_info/${detail.data.id}`,(value):value is MerchantOrderCart[]=>Array.isArray(value)&&value.length<=500&&value.every(isMerchantCart)),controller.read('delivery',isMerchantAgents),controller.read('export_all',isMerchantCarriers)]);if(!valid())return;if(gain.data.id!==detail.data.id||gain.data.order_id!==detail.data.order_id||gain.data.revision!==detail.data.revision)throw Error('发货订单依据已变化，请重新读取');order.value=detail.data;defaults.value=shipping.data;carts.value=cartRows.data;agents.value=staff.data;carriers.value=express.data;if(detail.data.product_type!==0)type.value=3;}});
const deliveryModes=computed(()=>[{type:1,label:'手工快递',disabled:order.value?.product_type!==0},{type:2,label:'门店配送',disabled:order.value?.product_type!==0||!defaults.value?.self_delivery_status},{type:3,label:'虚拟发货',disabled:order.value?.product_type!==3}]);
function chooseCarrier(event:{detail:{value:string|number}}){carrierIndex.value=Number(event.detail.value);}function chooseAgent(event:{detail:{value:string|number}}){agentIndex.value=Number(event.detail.value);}function toggle(cart:MerchantOrderCart){quantities.value[cart.cart_id]=quantities.value[cart.cart_id]?0:cart.split_surplus_num;}function quantity(cart:MerchantOrderCart,delta:number){quantities.value[cart.cart_id]=Math.max(0,Math.min(cart.split_surplus_num,(quantities.value[cart.cart_id]||0)+delta));}
async function submit(){const detail=order.value,authority=manager.context.value;if(!detail||!authority||manager.busy.value||!(split.value?detail.actions.split_delivery.available&&authority.data.capabilities.split_delivery:detail.actions.manual_delivery.available&&authority.data.capabilities.manual_delivery))return;error.value='';try{let payload:Record<string,unknown>;
  if(detail.product_type===0&&type.value===3||detail.product_type===3&&type.value!==3)throw Error('当前商品类型与发货方式不符');if(type.value===1){const carrier=carriers.value[carrierIndex.value];if(!carrier||!tracking.value.trim())throw Error('请选择快递公司并填写真实单号');payload={type:1,express_record_type:1,delivery_name:carrier.name,delivery_code:carrier.code,delivery_id:tracking.value.trim()};}
  else if(type.value===2){const agent=agents.value[agentIndex.value];if(!agent||!defaults.value?.self_delivery_status)throw Error('请选择当前门店可用配送员');payload={type:2,delivery_type:1,delivery_uid:agent.uid};}
  else{if(!content.value.trim()||content.value.trim().length>500)throw Error('请填写不超过 500 字的真实交付内容');payload={type:3,fictitious_content:content.value.trim()};}
  if(split.value){const cart_ids=carts.value.filter(cart=>(quantities.value[cart.cart_id]||0)>0).map(cart=>({cart_id:cart.cart_id,cart_num:quantities.value[cart.cart_id]!}));if(!cart_ids.length)throw Error('请选中本次发货商品和数量');payload={...payload,cart_ids};}
  const kind=split.value?'split_delivery':'manual_delivery',body={version:'merchant-order-operation-v1',store_id:detail.store_id,scope_key:authority.scope_key,order_id:detail.id,expected_order_revision:detail.revision,payload};
  const confirmed=await new Promise<boolean>(resolve=>uni.showModal({title:'核对本次发货',content:`订单 ${detail.order_id}，${split.value?'选中商品':'整单'}发货。确认真实物流或交付内容后提交。`,success:answer=>resolve(answer.confirm),fail:()=>resolve(false)}));if(!confirmed||!manager.current()||order.value!==detail)return;
  const result=await manager.execute({action:kind,order_id:detail.order_id,endpoint:`/store/manager/order/${split.value?'split_delivery':'delivery'}`,body,receipt_path:'/store/manager/order/operation/{requestKey}',receipt_method:'GET',abandon_path:`/store/manager/order/operation/abandon/${kind}`});if(!manager.current()||!result)return;if(result.outcome!=='delivery-recorded'){error.value='发货未执行，请核对并确认原操作记录。';return;}uni.showToast({title:'发货已确认',icon:'success'});manager.go('orderDetail',{orderId:detail.order_id});
}catch(failure){if(manager.current())error.value=manager.unresolved.value.some(intent=>intent.order_id===detail.order_id)?'原发货结果待确认，请先查询原操作。':failure instanceof Error?failure.message:'尚未提交';}}
</script>
